import{_ as l,b as t,c as e,g as n}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"深度学习","description":"","frontmatter":{"title":"深度学习","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach/21.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach/21.md"}'),o={name:"articles/artificial-intelligence/books/AI-modern-approach/21.md"};function r(a,i,s,d,c,g){return t(),e("div",null,[...i[0]||(i[0]=[n('<p>第 21 章介绍深度学习的基本原理和主要架构，核心是通过多层神经网络自动学习层次化特征表示。重点包括：</p><h2 id="神经网络基础" tabindex="-1">神经网络基础</h2><ul><li><strong>前向传播</strong>：净输入 z = w·x + b，激活函数（Sigmoid、ReLU、tanh）</li><li><strong>损失函数</strong>：均方误差（回归）、二元交叉熵（分类）</li><li><strong>反向传播</strong>：链式法则计算梯度，逐层更新权重和偏置</li></ul><h2 id="训练技巧" tabindex="-1">训练技巧</h2><ul><li><strong>梯度消失与梯度爆炸</strong>：深层网络训练困难的原因</li><li>缓解方法：ReLU 激活、批归一化、残差连接、梯度裁剪</li><li><strong>学习率、优化器</strong>（SGD、Adam）的选择</li></ul><h2 id="卷积神经网络-cnn" tabindex="-1">卷积神经网络（CNN）</h2><ul><li>卷积层、池化层、全连接层的参数计算</li><li>感受野、参数共享、平移不变性</li><li>应用于图像分类、目标检测等</li></ul><h2 id="循环神经网络-rnn" tabindex="-1">循环神经网络（RNN）</h2><ul><li>处理序列数据的循环结构</li><li><strong>LSTM / GRU</strong>：门控机制缓解长期依赖问题</li><li>应用于时间序列预测、文本生成</li></ul><h2 id="生成模型" tabindex="-1">生成模型</h2><ul><li><strong>生成对抗网络（GAN）</strong>：生成器与判别器的极小极大博弈</li><li><strong>变分自编码器（VAE）</strong>：概率生成模型</li><li>模式崩溃、训练不稳定等常见问题</li></ul><h2 id="实践要点" tabindex="-1">实践要点</h2><ul><li>数据预处理（归一化、数据增强）</li><li>过拟合判断与正则化（Dropout、早停）</li><li>预训练 + 微调、半监督学习应对标注数据不足</li></ul>',13)])])}const u=l(o,[["render",r]]);export{p as __pageData,u as default};
